// Block (composition) — the action row that closes a customer screen: one full-width forward Button,
// or a pair (an outline secondary and the primary). A counter, a kiosk, a table order or a mobile POS
// ends its steps with it: 「바로 결제 | 메뉴 추가」, 「분할 | 결제하기」, 「주문하기」.
//
// Not FloatingBar: that floats inset over the page and reserves no space. This is the last row of a
// screen column whose middle scrolls, so it never covers content and needs no surface of its own. The
// consumer places it last in a full-height column, which supplies the page margin at the sides.
//
// The row is a ButtonGroup (component-usage.md § Two buttons side by side): `center` splits the width
// evenly between a pair, `stack` gives a single action the full width. This Block owns only the space
// below: at least `space.medium`, or the device's bottom safe area where that is larger. The safe area
// is reported only when the page's viewport meta sets `viewport-fit=cover`; without it, it reads 0.
//
// ponytail: a pair where the secondary hugs its label and the primary takes the rest (「분할 | 결제하기」)
// waits on a ButtonGroup layout for it (queued on the Sando side); until then a pair is halves.
import type { HTMLAttributes, ReactNode, Ref } from "react";
import { Button } from "../components/Button";
import { ButtonGroup } from "../components/ButtonGroup";
import "./BottomActionBar.css";

export interface BottomAction {
  /** The visible label, e.g. "14,500원 결제하기". */
  label: ReactNode;
  /** Called when pressed. */
  onPress: () => void;
  /** When true the action shows but cannot be pressed, e.g. before a required option is chosen. */
  isDisabled?: boolean;
}

export interface BottomActionBarProps extends Omit<HTMLAttributes<HTMLDivElement>, "className" | "role" | "aria-label"> {
  /**
   * Size of the Buttons. `large` on a customer screen read at arm's length.
   *
   * @default "large"
   */
  size?: "small" | "medium" | "large";
  /**
   * Wordless actions before the row, on the item the screen is about: a save heart, a share. Icon-only
   * Buttons, `ghost` (prop-usage-contract.md, the wordless law). The forward action then takes the
   * rest of the width.
   */
  leading?: ReactNode;
  /** The forward action: completes or advances the step. */
  primary: BottomAction;
  /** A second action beside it, drawn `outline`. */
  secondary?: BottomAction;
  /**
   * Accessible name of the row, e.g. "주문". It names the region landmark the row renders as, so a
   * screen reader can jump to the screen's closing actions, and a docked row outside `main` stays in a
   * landmark (axe `region`).
   */
  "aria-label": string;
  /** Additional class (optional). sd-bottom-action-bar is always preserved. */
  className?: string;
  /** Forwarded to the root element. */
  ref?: Ref<HTMLDivElement>;
}

export function BottomActionBar({
  size = "large",
  leading,
  primary,
  secondary,
  "aria-label": ariaLabel,
  className,
  ref,
  ...props
}: BottomActionBarProps) {
  return (
    <div
      {...props}
      ref={ref}
      role="region"
      aria-label={ariaLabel}
      className={className ? `sd-bottom-action-bar ${className}` : "sd-bottom-action-bar"}
      data-has-leading={leading ? "" : undefined}
    >
      {leading && <div className="sd-bottom-action-bar__leading">{leading}</div>}
      <ButtonGroup layout={secondary ? "center" : "stack"} className="sd-bottom-action-bar__actions">
        {secondary && (
          <Button variant="secondary" size={size} isDisabled={secondary.isDisabled} onPress={secondary.onPress}>
            {secondary.label}
          </Button>
        )}
        {/* usage: completing-action — the forward action of the step, the only primary in the row */}
        <Button variant="primary" size={size} isDisabled={primary.isDisabled} onPress={primary.onPress}>
          {primary.label}
        </Button>
      </ButtonGroup>
    </div>
  );
}

/* Layout only (block-contract.md §3, §5): the ButtonGroup lays out the row; this owns the space above
   and the device's safe area below. */
.sd-bottom-action-bar {
  padding-block: var(--sd-space-small) max(var(--sd-space-medium), env(safe-area-inset-bottom));
}

/* With wordless actions before it, the row runs inline: the icons hug their glyphs and the forward
   action takes the rest. The icons are transparent toggles of one cluster, so they sit flush
   (token-contract.md, action-row), and the cluster parts from the filled Button by `x-small`. */
.sd-bottom-action-bar[data-has-leading] {
  display: flex;
  align-items: center;
  gap: var(--sd-space-x-small);
}

.sd-bottom-action-bar__leading {
  display: flex;
  flex: none;
}

.sd-bottom-action-bar__actions {
  flex: 1 1 auto;
  min-width: 0;
}
